import { Inject, Injectable, Optional } from '@nestjs/common';
import { DatabaseService } from '../database/database.service.js';
import { uuidV7 } from '@handstack/domain';
import {
  WorkflowRuntime,
  RepositoryWorkflowStore,
  type WorkflowStore,
  type Workflow,
  type WorkflowEdge,
  type WorkflowExecution,
  type WorkflowNode,
  type WorkflowStepExecution,
  type WorkflowTrigger,
} from '@handstack/workflows';
import { ValidationError } from '@handstack/shared';
import { OperationsRuntimeService } from '../operations/operations-runtime.service.js';

export interface WorkflowDefinitionInput {
  readonly organizationId: string;
  readonly name: string;
  readonly trigger: WorkflowTrigger;
  readonly nodes: readonly WorkflowNode[];
  readonly edges: readonly WorkflowEdge[];
}

@Injectable()
export class WorkflowRuntimeService {
  private readonly workflows = new Map<string, Workflow>();
  private readonly store: WorkflowStore | undefined;
  private readonly runtime: WorkflowRuntime;

  constructor(
    @Optional() @Inject(DatabaseService) database?: DatabaseService,
    @Optional()
    @Inject(OperationsRuntimeService)
    private readonly operations?: OperationsRuntimeService,
  ) {
    this.store =
      database === undefined
        ? undefined
        : new RepositoryWorkflowStore((name) => database.adapter.repository(name));
    this.runtime = new WorkflowRuntime((node, input) => {
      // Core nodes are intentionally side-effect free here. Providers can replace this executor.
      if (node.kind === 'Condition' && typeof node.config.pass === 'boolean' && !node.config.pass)
        return Promise.resolve({ input, skipped: true });
      return Promise.resolve(input);
    }, this.store);
  }

  async list(organizationId: string): Promise<readonly Workflow[]> {
    const durable = (await this.store?.listWorkflows(organizationId)) ?? [];
    for (const workflow of durable) {
      this.workflows.set(this.key(organizationId, workflow.id), workflow);
      this.runtime.register(workflow);
    }
    return [...this.workflows.values()].filter(
      (workflow) => workflow.organizationId === organizationId,
    );
  }

  async get(organizationId: string, workflowId: string): Promise<Workflow> {
    const workflow = this.workflows.get(this.key(organizationId, workflowId));
    if (workflow?.organizationId === organizationId) return workflow;
    const durable = await this.store?.findWorkflow(organizationId, workflowId);
    if (durable === undefined) throw new ValidationError('Workflow not found');
    this.workflows.set(this.key(organizationId, workflowId), durable);
    this.runtime.register(durable);
    return durable;
  }

  async create(input: WorkflowDefinitionInput): Promise<Workflow> {
    const now = new Date();
    const workflow: Workflow = {
      id: uuidV7(),
      tenantId: input.organizationId,
      organizationId: input.organizationId,
      name: input.name,
      trigger: input.trigger,
      nodes: input.nodes,
      edges: input.edges,
      published: false,
      version: 1,
      createdAt: now,
      updatedAt: now,
    };
    this.runtime.register(workflow);
    this.workflows.set(this.key(input.organizationId, workflow.id), workflow);
    await this.store?.saveWorkflow(workflow);
    return workflow;
  }

  async publish(organizationId: string, workflowId: string): Promise<Workflow> {
    const current = await this.get(organizationId, workflowId);
    const published: Workflow = { ...current, published: true, updatedAt: new Date() };
    this.runtime.register(published);
    this.workflows.set(this.key(organizationId, workflowId), published);
    await this.store?.saveWorkflow(published);
    return published;
  }

  start(input: {
    readonly organizationId: string;
    readonly workflowId: string;
    readonly principalId: string;
    readonly trigger: WorkflowTrigger;
    readonly payload: unknown;
    readonly signal?: AbortSignal;
  }): Promise<WorkflowExecution> {
    return this.get(input.organizationId, input.workflowId).then(async () => {
      const execution = await this.runtime.start(input);
      return execution;
    });
  }

  async startAsync(input: {
    readonly organizationId: string;
    readonly workflowId: string;
    readonly principalId: string;
    readonly trigger: WorkflowTrigger;
    readonly payload: unknown;
    readonly idempotencyKey: string;
    readonly signal?: AbortSignal;
  }) {
    if (this.operations === undefined)
      throw new ValidationError('Operations runtime is required for asynchronous workflows');
    const operation = await this.operations.createOperation({
      organizationId: input.organizationId,
      type: `workflow:${input.workflowId}`,
      idempotencyKey: input.idempotencyKey,
    });
    if (operation.status !== 'PENDING') return operation;
    if (input.signal?.aborted) {
      try {
        return await this.operations.operations.update(
          { ...operation, status: 'CANCELLED', cancelRequested: true },
          operation.version,
        );
      } catch {
        return operation;
      }
    }
    let running: typeof operation;
    try {
      running = await this.operations.operations.update(
        { ...operation, status: 'RUNNING' },
        operation.version,
      );
    } catch {
      // A concurrent cancellation may have advanced the operation before work started.
      return operation;
    }
    const controller = new AbortController();
    const onAbort = () => controller.abort();
    if (input.signal?.aborted) controller.abort();
    else input.signal?.addEventListener('abort', onAbort, { once: true });
    const cancellationTimer = setInterval(() => {
      void this.operations?.getOperation(input.organizationId, running.id).then((current) => {
        if (current?.cancelRequested === true || current?.status === 'CANCELLED')
          controller.abort();
      });
    }, 50);
    void this.start({
      organizationId: input.organizationId,
      workflowId: input.workflowId,
      principalId: input.principalId,
      trigger: input.trigger,
      payload: input.payload,
      signal: controller.signal,
    })
      .then(async (execution) => {
        try {
          await this.operations?.operations.update(
            {
              ...running,
              status: controller.signal.aborted
                ? 'CANCELLED'
                : execution.status === 'COMPLETED'
                  ? 'SUCCEEDED'
                  : 'FAILED',
              ...(execution.status === 'COMPLETED'
                ? { result: { executionId: execution.id } }
                : { errorCode: execution.error ?? 'workflow_execution_failed' }),
            },
            running.version,
          );
        } catch {
          // A concurrent API cancellation already advanced the Operation version.
        }
      })
      .catch(async (error: unknown) => {
        try {
          await this.operations?.operations.update(
            {
              ...running,
              status: controller.signal.aborted ? 'CANCELLED' : 'FAILED',
              errorCode: controller.signal.aborted
                ? 'workflow_execution_cancelled'
                : error instanceof ValidationError
                  ? error.code
                  : 'workflow_execution_failed',
            },
            running.version,
          );
        } catch {
          // A concurrent API cancellation already advanced the Operation version.
        }
      })
      .finally(() => {
        clearInterval(cancellationTimer);
        input.signal?.removeEventListener('abort', onAbort);
      });
    return operation;
  }

  async getExecution(organizationId: string, executionId: string): Promise<WorkflowExecution> {
    const execution = this.runtime.get(organizationId, executionId);
    if (execution !== undefined) return execution;
    const durable = await this.store?.findExecution(organizationId, executionId);
    if (durable === undefined) throw new ValidationError('Workflow execution not found');
    const workflow = await this.get(organizationId, durable.workflowId);
    await this.runtime.hydrate(durable, workflow);
    return durable;
  }

  async listSteps(
    organizationId: string,
    executionId: string,
  ): Promise<readonly WorkflowStepExecution[]> {
    const execution = await this.getExecution(organizationId, executionId);
    const steps = await this.store?.listSteps(organizationId, execution.id);
    return steps ?? this.runtime.listSteps(organizationId, execution.id);
  }

  async approve(input: {
    readonly organizationId: string;
    readonly executionId: string;
    readonly approverId: string;
  }): Promise<WorkflowExecution> {
    const execution = await this.getExecution(input.organizationId, input.executionId);
    if (execution.status !== 'WAITING_APPROVAL' || execution.approvalId === undefined)
      throw new ValidationError('Workflow execution is not waiting for approval');
    await this.runtime.approve(input.organizationId, execution.approvalId, input.approverId);
    const resumed = await this.runtime.resume(
      input.organizationId,
      input.executionId,
      execution.approvalId,
    );
    return resumed;
  }

  async recover(input: {
    readonly organizationId: string;
    readonly executionId: string;
  }): Promise<WorkflowExecution> {
    const execution = await this.getExecution(input.organizationId, input.executionId);
    if (execution.status !== 'RUNNING' && execution.status !== 'FAILED')
      throw new ValidationError('Workflow execution is not recoverable');
    return this.runtime.recover(input.organizationId, input.executionId);
  }

  private key(organizationId: string, id: string): string {
    return `${organizationId}:${id}`;
  }
}
--- workflow controller ---
import { AuthorizationError, ValidationError } from '@handstack/shared';
import {
  Body,
  Controller,
  Get,
  Headers,
  HttpCode,
  HttpStatus,
  Inject,
  Param,
  Post,
  Req,
  UseGuards,
} from '@nestjs/common';
import { ApiBearerAuth, ApiHeader, ApiOperation, ApiTags } from '@nestjs/swagger';
import { z } from 'zod';
import { AccessTokenGuard } from '../auth/access-token.guard.js';
import { AuthRuntimeService } from '../auth/auth-runtime.service.js';
import {
  requireAuthentication,
  type AuthenticatedRequest,
} from '../auth/authentication-context.js';
import { IdentityAdministrationService } from '@handstack/identity-service';
import { WorkflowRuntimeService } from './workflow-runtime.service.js';

const nodeSchema = z.object({
  id: z.string().trim().min(1).max(128),
  kind: z.enum(['Agent', 'Capability', 'LLM', 'Tool', 'MCP', 'Condition', 'Human Approval']),
  config: z.record(z.string(), z.unknown()).default({}),
});
const edgeSchema = z.object({
  from: z.string().trim().min(1).max(128),
  to: z.string().trim().min(1).max(128),
  condition: z.string().max(2_000).optional(),
});
const createSchema = z.object({
  name: z.string().trim().min(1).max(200),
  trigger: z.enum(['manual', 'api', 'webhook', 'schedule', 'event']),
  nodes: z.array(nodeSchema).min(1).max(100),
  edges: z.array(edgeSchema).max(200),
});
const startSchema = z.object({
  trigger: z.enum(['manual', 'api', 'webhook', 'schedule', 'event']),
  payload: z.unknown(),
});
const approveSchema = z.object({ approverId: z.string().trim().min(1).max(200) });

@ApiTags('Workflows')
@ApiBearerAuth()
@Controller('api/v1/organizations/:organizationId/workflows')
@UseGuards(AccessTokenGuard)
export class WorkflowController {
  private readonly administration: IdentityAdministrationService;

  constructor(
    @Inject(WorkflowRuntimeService) private readonly runtime: WorkflowRuntimeService,
    @Inject(AuthRuntimeService) auth: AuthRuntimeService,
  ) {
    this.administration = new IdentityAdministrationService(auth.storage);
  }

  @Get()
  @ApiOperation({ summary: 'List workflows for an organization' })
  async list(
    @Param('organizationId') organizationId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.read');
    return { items: await this.runtime.list(organizationId) };
  }

  @Post()
  @ApiOperation({ summary: 'Create a workflow draft' })
  async create(
    @Param('organizationId') organizationId: string,
    @Req() request: AuthenticatedRequest,
    @Body() value: unknown,
  ) {
    await this.authorize(organizationId, request, 'workflows.manage');
    const parsed = createSchema.safeParse(value);
    if (!parsed.success)
      throw new ValidationError(parsed.error.issues[0]?.message ?? 'Invalid workflow');
    return this.runtime.create({
      organizationId,
      name: parsed.data.name,
      trigger: parsed.data.trigger,
      nodes: parsed.data.nodes,
      edges: parsed.data.edges.map((edge) =>
        edge.condition === undefined
          ? { from: edge.from, to: edge.to }
          : { from: edge.from, to: edge.to, condition: edge.condition },
      ),
    });
  }

  @Post(':workflowId/publish')
  @ApiOperation({ summary: 'Publish a workflow' })
  async publish(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.manage');
    return this.runtime.publish(organizationId, workflowId);
  }

  @Post(':workflowId/executions')
  @HttpCode(HttpStatus.ACCEPTED)
  @ApiHeader({ name: 'Idempotency-Key', required: true })
  @ApiOperation({ summary: 'Start a workflow execution' })
  async start(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Headers('idempotency-key') idempotencyKey: string | undefined,
    @Req() request: AuthenticatedRequest,
    @Body() value: unknown,
  ) {
    const authentication = await this.authorize(organizationId, request, 'workflows.run');
    const parsed = startSchema.safeParse(value);
    if (!parsed.success)
      throw new ValidationError(parsed.error.issues[0]?.message ?? 'Invalid execution');
    if (idempotencyKey === undefined || idempotencyKey.trim() === '')
      throw new ValidationError('Idempotency-Key is required');
    return this.runtime.startAsync({
      organizationId,
      workflowId,
      principalId: authentication.subject,
      ...parsed.data,
      idempotencyKey: idempotencyKey.trim(),
    });
  }

  @Get(':workflowId/executions/:executionId')
  @ApiOperation({ summary: 'Get workflow execution' })
  async getExecution(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Param('executionId') executionId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.read');
    const execution = await this.runtime.getExecution(organizationId, executionId);
    if (execution.workflowId !== workflowId)
      throw new ValidationError('Workflow execution not found');
    return execution;
  }

  @Get(':workflowId/executions/:executionId/steps')
  @ApiOperation({ summary: 'List workflow step execution history' })
  async listSteps(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Param('executionId') executionId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.read');
    const execution = await this.runtime.getExecution(organizationId, executionId);
    if (execution.workflowId !== workflowId)
      throw new ValidationError('Workflow execution not found');
    return { items: await this.runtime.listSteps(organizationId, executionId) };
  }

  @Post(':workflowId/executions/:executionId/approve')
  @ApiOperation({ summary: 'Approve and resume a workflow execution' })
  async approve(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Param('executionId') executionId: string,
    @Req() request: AuthenticatedRequest,
    @Body() value: unknown,
  ) {
    const authentication = await this.authorize(organizationId, request, 'workflows.run');
    const current = await this.runtime.getExecution(organizationId, executionId);
    if (current.workflowId !== workflowId)
      throw new ValidationError('Workflow execution not found');
    const parsed = approveSchema.safeParse(value);
    if (!parsed.success || parsed.data.approverId !== authentication.subject)
      throw new AuthorizationError('Approver must match authenticated principal');
    return this.runtime.approve({
      organizationId,
      executionId,
      approverId: parsed.data.approverId,
    });
  }

  @Post(':workflowId/executions/:executionId/recover')
  @ApiOperation({ summary: 'Recover a workflow execution after a process failure' })
  async recover(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Param('executionId') executionId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.run');
    const current = await this.runtime.getExecution(organizationId, executionId);
    if (current.workflowId !== workflowId)
      throw new ValidationError('Workflow execution not found');
    return this.runtime.recover({ organizationId, executionId });
  }

  private async authorize(
    organizationId: string,
    request: AuthenticatedRequest,
    permission: string,
  ) {
    const authentication = requireAuthentication(request);
    if (authentication.organizationId !== organizationId)
      throw new AuthorizationError('Cross-organization workflow access is forbidden');
    const decision = await this.administration.authorize({
      organizationId,
      principalId: authentication.subject,
      permission,
    });
    if (!decision.allowed) throw new AuthorizationError(`${permission} permission is required`);
    return authentication;
  }
}
--- workflow package ---
import {
  uuidV7,
  type Repository,
  type RepositoryName,
  type TenantEntity,
  repositoryName,
} from '@handstack/domain';
import { InMemoryApprovalService } from '@handstack/policy';
import { ValidationError } from '@handstack/shared';

export type WorkflowTrigger = 'manual' | 'api' | 'webhook' | 'schedule' | 'event';
export type WorkflowNodeKind =
  'Agent' | 'Capability' | 'LLM' | 'Tool' | 'MCP' | 'Condition' | 'Human Approval';
export type WorkflowExecutionStatus =
  | 'RUNNING'
  | 'WAITING_APPROVAL'
  | 'COMPLETED'
  | 'FAILED'
  | 'CANCELLED'
  | 'TIMED_OUT';

export interface WorkflowNode {
  readonly id: string;
  readonly kind: WorkflowNodeKind;
  readonly config: Readonly<Record<string, unknown>>;
}

export interface WorkflowEdge {
  readonly from: string;
  readonly to: string;
  readonly condition?: string;
}

export interface Workflow extends TenantEntity {
  readonly organizationId: string;
  readonly name: string;
  readonly trigger: WorkflowTrigger;
  readonly nodes: readonly WorkflowNode[];
  readonly edges: readonly WorkflowEdge[];
  readonly published: boolean;
}

export interface WorkflowExecution extends TenantEntity {
  readonly organizationId: string;
  readonly workflowId: string;
  readonly principalId: string;
  readonly status: WorkflowExecutionStatus;
  readonly input: unknown;
  readonly output?: unknown;
  readonly currentNodeId?: string;
  readonly approvalId?: string;
  readonly error?: string;
}

export interface WorkflowStepExecution extends TenantEntity {
  readonly organizationId: string;
  readonly executionId: string;
  readonly nodeId: string;
  readonly status:
    | 'RUNNING'
    | 'COMPLETED'
    | 'WAITING_APPROVAL'
    | 'FAILED'
    | 'CANCELLED'
    | 'TIMED_OUT';
  readonly input: unknown;
  readonly output?: unknown;
  readonly startedAt: Date;
  readonly completedAt?: Date;
}

export interface WorkflowStore {
  saveWorkflow(workflow: Workflow): Promise<Workflow>;
  listWorkflows(organizationId: string): Promise<readonly Workflow[]>;
  findWorkflow(organizationId: string, workflowId: string): Promise<Workflow | undefined>;
  saveExecution(execution: WorkflowExecution): Promise<WorkflowExecution>;
  findExecution(
    organizationId: string,
    executionId: string,
  ): Promise<WorkflowExecution | undefined>;
  saveStep(step: WorkflowStepExecution): Promise<WorkflowStepExecution>;
  listSteps(organizationId: string, executionId: string): Promise<readonly WorkflowStepExecution[]>;
}

/** Adapter-neutral durable store backed by the canonical tenant repository contract. */
export class RepositoryWorkflowStore implements WorkflowStore {
  private readonly workflows: Repository<Workflow>;
  private readonly executions: Repository<WorkflowExecution>;
  private readonly steps: Repository<WorkflowStepExecution>;
  constructor(repository: <T extends TenantEntity>(name: RepositoryName) => Repository<T>) {
    this.workflows = repository<Workflow>(repositoryName('workflows'));
    this.executions = repository<WorkflowExecution>(repositoryName('workflow-executions'));
    this.steps = repository<WorkflowStepExecution>(repositoryName('workflow-steps'));
  }
  saveWorkflow(workflow: Workflow): Promise<Workflow> {
    return this.persist(this.workflows, workflow);
  }
  findWorkflow(organizationId: string, workflowId: string): Promise<Workflow | undefined> {
    return this.workflows.findById(organizationId, workflowId);
  }
  async listWorkflows(organizationId: string): Promise<readonly Workflow[]> {
    const items: Workflow[] = [];
    let cursor: string | undefined;
    do {
      const page = await this.workflows.list(organizationId, {
        limit: 200,
        ...(cursor === undefined ? {} : { cursor }),
      });
      items.push(...page.items);
      if (page.nextCursor !== undefined && page.nextCursor === cursor)
        throw new ValidationError('Workflow repository cursor repeated');
      cursor = page.nextCursor;
    } while (cursor !== undefined);
    return items;
  }
  saveExecution(execution: WorkflowExecution): Promise<WorkflowExecution> {
    return this.persist(this.executions, execution);
  }
  findExecution(
    organizationId: string,
    executionId: string,
  ): Promise<WorkflowExecution | undefined> {
    return this.executions.findById(organizationId, executionId);
  }
  saveStep(step: WorkflowStepExecution): Promise<WorkflowStepExecution> {
    return this.persist(this.steps, step);
  }
  async listSteps(
    organizationId: string,
    executionId: string,
  ): Promise<readonly WorkflowStepExecution[]> {
    const items: WorkflowStepExecution[] = [];
    let cursor: string | undefined;
    do {
      const page = await this.steps.list(organizationId, {
        limit: 200,
        ...(cursor === undefined ? {} : { cursor }),
      });
      items.push(...page.items.filter((step) => step.executionId === executionId));
      if (page.nextCursor !== undefined && page.nextCursor === cursor)
        throw new ValidationError('Workflow repository cursor repeated');
      cursor = page.nextCursor;
    } while (cursor !== undefined);
    return items;
  }
  private async persist<T extends TenantEntity>(repository: Repository<T>, entity: T): Promise<T> {
    const current = await repository.findById(entity.tenantId, entity.id);
    return current === undefined
      ? repository.insert(entity)
      : repository.update(entity, current.version);
  }
}

export type WorkflowNodeExecutor = (
  node: WorkflowNode,
  input: unknown,
  context: {
    readonly organizationId: string;
    readonly principalId: string;
    readonly signal?: AbortSignal;
  },
) => Promise<unknown>;

export class WorkflowRuntime {
  private readonly workflows = new Map<string, Workflow>();
  private readonly executions = new Map<string, WorkflowExecution>();
  private readonly steps = new Map<string, WorkflowStepExecution>();
  private readonly approvals = new InMemoryApprovalService();

  constructor(
    private readonly executeNode: WorkflowNodeExecutor,
    private readonly store?: WorkflowStore,
  ) {}

  register(workflow: Workflow): void {
    validateWorkflow(workflow);
    const key = `${workflow.organizationId}:${workflow.id}`;
    const current = this.workflows.get(key);
    if (
      current?.published === true &&
      (!workflow.published || !sameWorkflowGraph(current, workflow))
    )
      throw new ValidationError('Published workflow graph is immutable');
    this.workflows.set(key, workflow);
  }

  async start(input: {
    readonly organizationId: string;
    readonly workflowId: string;
    readonly principalId: string;
    readonly trigger: WorkflowTrigger;
    readonly payload: unknown;
    readonly signal?: AbortSignal;
  }): Promise<WorkflowExecution> {
    const workflow = this.require(input.organizationId, input.workflowId);
    if (!workflow.published || workflow.trigger !== input.trigger)
      throw new ValidationError('Workflow is not published for this trigger');
    const execution: WorkflowExecution = {
      id: uuidV7(),
      tenantId: input.organizationId,
      organizationId: input.organizationId,
      workflowId: workflow.id,
      principalId: input.principalId,
      status: 'RUNNING',
      input: input.payload,
      version: 1,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    this.executions.set(this.key(input.organizationId, execution.id), execution);
    await this.persistExecution(execution);
    return this.run(execution, workflow, input.signal);
  }

  async resume(
    organizationId: string,
    executionId: string,
    approvalId: string,
    signal?: AbortSignal,
  ): Promise<WorkflowExecution> {
    const execution = this.executions.get(this.key(organizationId, executionId));
    if (execution?.status !== 'WAITING_APPROVAL')
      throw new ValidationError('Workflow execution is not waiting for approval');
    await this.approvals.requireApproved(organizationId, approvalId);
    const workflow = this.require(organizationId, execution.workflowId);
    const nextNode = workflow.edges.find((edge) => edge.from === execution.currentNodeId)?.to;
    return this.run({ ...execution, status: 'RUNNING' }, workflow, signal, nextNode);
  }

  async recover(
    organizationId: string,
    executionId: string,
    signal?: AbortSignal,
  ): Promise<WorkflowExecution> {
    const execution = this.executions.get(this.key(organizationId, executionId));
    if (execution?.status !== 'RUNNING' && execution?.status !== 'FAILED')
      throw new ValidationError('Workflow execution is not recoverable');
    const workflow = this.require(organizationId, execution.workflowId);
    const checkpoints =
      this.store === undefined
        ? this.listSteps(organizationId, executionId)
        : await this.store.listSteps(organizationId, executionId);
    const lastCompleted = [...checkpoints]
      .filter((step) => step.status === 'COMPLETED')
      .sort(
        (left, right) =>
          (right.completedAt?.getTime() ?? 0) - (left.completedAt?.getTime() ?? 0),
      )[0];
    return this.run(
      execution,
      workflow,
      signal,
      execution.currentNodeId,
      lastCompleted === undefined ? execution.input : lastCompleted.output,
    );
  }

  async hydrate(execution: WorkflowExecution, workflow: Workflow): Promise<void> {
    this.require(execution.organizationId, workflow.id);
    if (this.executions.has(this.key(execution.organizationId, execution.id))) return;
    this.executions.set(this.key(execution.organizationId, execution.id), execution);
    if (execution.status !== 'WAITING_APPROVAL' || execution.approvalId === undefined) return;
    const node = workflow.nodes.find((candidate) => candidate.id === execution.currentNodeId);
    if (node?.kind !== 'Human Approval')
      throw new ValidationError('Workflow approval node not found');
    await this.approvals.request({
      id: execution.approvalId,
      organizationId: execution.organizationId,
      requesterId: execution.principalId,
      resource: `workflow:${workflow.id}`,
      action: 'continue',
      payloadDigest: execution.id,
      requiredApprovers: asApprovers(node.config.approvers),
    });
  }

  listSteps(organizationId: string, executionId: string): readonly WorkflowStepExecution[] {
    return [...this.steps.values()]
      .filter((step) => step.organizationId === organizationId && step.executionId === executionId)
      .sort((left, right) => left.startedAt.getTime() - right.startedAt.getTime());
  }

  async approve(organizationId: string, approvalId: string, approverId: string) {
    return this.approvals.approve(organizationId, approvalId, approverId);
  }
  get(organizationId: string, executionId: string) {
    return this.executions.get(this.key(organizationId, executionId));
  }

  private async run(
    execution: WorkflowExecution,
    workflow: Workflow,
    signal?: AbortSignal,
    startNodeId?: string,
    initialValue: unknown = execution.input,
  ): Promise<WorkflowExecution> {
    let current = startNodeId ?? workflow.nodes[0]?.id;
    let value = initialValue;
    let currentExecution = execution;
    let activeStep: WorkflowStepExecution | undefined;
    try {
      while (current !== undefined) {
        if (signal?.aborted === true) throw new Error('Workflow execution cancelled');
        const node = workflow.nodes.find((candidate) => candidate.id === current);
        if (node === undefined) throw new ValidationError('Workflow node not found');
        currentExecution = {
          ...currentExecution,
          status: 'RUNNING',
          currentNodeId: node.id,
          updatedAt: new Date(),
        };
        this.executions.set(this.key(execution.organizationId, execution.id), currentExecution);
        await this.persistExecution(currentExecution);
        const step: WorkflowStepExecution = {
          id: uuidV7(),
          tenantId: execution.organizationId,
          organizationId: execution.organizationId,
          executionId: execution.id,
          nodeId: node.id,
          status: 'RUNNING',
          input: value,
          version: 1,
          startedAt: new Date(),
          createdAt: new Date(),
          updatedAt: new Date(),
        };
        activeStep = step;
        this.steps.set(this.key(execution.organizationId, step.id), step);
        await this.persistStep(step);
        if (node.kind === 'Human Approval') {
          const approval = await this.approvals.request({
            id: uuidV7(),
            organizationId: execution.organizationId,
            requesterId: execution.principalId,
            resource: `workflow:${workflow.id}`,
            action: 'continue',
            payloadDigest: execution.id,
            requiredApprovers: asApprovers(node.config.approvers),
          });
          const waiting = {
            ...currentExecution,
            status: 'WAITING_APPROVAL' as const,
            currentNodeId: node.id,
            approvalId: approval.id,
            updatedAt: new Date(),
          };
          this.executions.set(this.key(execution.organizationId, execution.id), waiting);
          const waitingStep = {
            ...step,
            status: 'WAITING_APPROVAL' as const,
            output: approval.id,
            completedAt: new Date(),
          };
          activeStep = waitingStep;
          this.steps.set(this.key(execution.organizationId, step.id), waitingStep);
          await this.persistStep(waitingStep);
          await this.persistExecution(waiting);
          return waiting;
        }
        value = await this.executeNodeWithRetry(node, value, {
          organizationId: execution.organizationId,
          principalId: execution.principalId,
          ...(signal === undefined ? {} : { signal }),
        });
        assertOutputWithinLimit(node, value);
        if (signal?.aborted === true) throw new Error('Workflow execution cancelled');
        const completedStep = {
          ...step,
          status: 'COMPLETED' as const,
          output: value,
          completedAt: new Date(),
        };
        activeStep = completedStep;
        this.steps.set(this.key(execution.organizationId, step.id), completedStep);
        await this.persistStep(completedStep);
        current = nextNode(workflow.edges, node.id, value);
        currentExecution = {
          ...currentExecution,
          ...(current === undefined ? {} : { currentNodeId: current }),
          updatedAt: new Date(),
        };
        this.executions.set(this.key(execution.organizationId, execution.id), currentExecution);
        await this.persistExecution(currentExecution);
      }
      const completed = {
        ...currentExecution,
        status: 'COMPLETED' as const,
        output: value,
        updatedAt: new Date(),
      };
      this.executions.set(this.key(execution.organizationId, execution.id), completed);
      await this.persistExecution(completed);
      return completed;
    } catch (error) {
      const timedOut = error instanceof WorkflowTimeoutError && signal?.aborted !== true;
      if (activeStep?.status === 'RUNNING') {
        const failedStep = {
          ...activeStep,
          status: timedOut
            ? ('TIMED_OUT' as const)
            : signal?.aborted === true
              ? ('CANCELLED' as const)
              : ('FAILED' as const),
          completedAt: new Date(),
        };
        this.steps.set(this.key(execution.organizationId, failedStep.id), failedStep);
        await this.persistStep(failedStep);
      }
      const failed = {
        ...currentExecution,
        status: timedOut
          ? ('TIMED_OUT' as const)
          : signal?.aborted === true
            ? ('CANCELLED' as const)
            : ('FAILED' as const),
        error:
          timedOut
            ? 'workflow_step_timeout'
            : error instanceof WorkflowOutputLimitError
              ? 'workflow_output_too_large'
              : error instanceof WorkflowOutputSerializationError
                ? 'workflow_output_invalid'
                : signal?.aborted === true
                  ? 'workflow_execution_cancelled'
                  : error instanceof Error
                    ? error.message
                    : String(error),
        updatedAt: new Date(),
      };
      this.executions.set(this.key(execution.organizationId, execution.id), failed);
      await this.persistExecution(failed);
      return failed;
    }
  }

  private executeNodeWithTimeout(
    node: WorkflowNode,
    input: unknown,
    context: { readonly organizationId: string; readonly principalId: string; readonly signal?: AbortSignal },
  ): Promise<unknown> {
    const timeout = timeoutMs(node);
    if (timeout === undefined) return this.executeNode(node, input, context);
    const controller = new AbortController();
    const forwardAbort = () => controller.abort();
    if (context.signal?.aborted === true) controller.abort();
    else context.signal?.addEventListener('abort', forwardAbort, { once: true });
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        controller.abort();
        reject(new WorkflowTimeoutError());
      }, timeout);
      void this.executeNode(node, input, { ...context, signal: controller.signal })
        .then(resolve, reject)
        .finally(() => {
          clearTimeout(timer);
          context.signal?.removeEventListener('abort', forwardAbort);
        });
    });
  }

  private async executeNodeWithRetry(
    node: WorkflowNode,
    input: unknown,
    context: { readonly organizationId: string; readonly principalId: string; readonly signal?: AbortSignal },
  ): Promise<unknown> {
    const policy = retryPolicy(node);
    for (let attempt = 1; ; attempt += 1) {
      try {
        return await this.executeNodeWithTimeout(node, input, context);
      } catch (error) {
        if (attempt >= policy.maxAttempts || context.signal?.aborted === true) throw error;
        if (policy.backoffMs > 0)
          await waitForRetryBackoff(policy.backoffMs, context.signal);
        if (context.signal?.aborted === true) throw error;
      }
    }
  }

  private persistExecution(execution: WorkflowExecution): Promise<WorkflowExecution> {
    return this.store === undefined
      ? Promise.resolve(execution)
      : this.store.saveExecution(execution);
  }

  private persistStep(step: WorkflowStepExecution): Promise<WorkflowStepExecution> {
    return this.store === undefined ? Promise.resolve(step) : this.store.saveStep(step);
  }

  private require(organizationId: string, workflowId: string) {
    const workflow = this.workflows.get(this.key(organizationId, workflowId));
    if (workflow === undefined) throw new ValidationError('Workflow not found');
    return workflow;
  }
  private key(organizationId: string, id: string) {
    return `${organizationId}:${id}`;
  }
}

function validateWorkflow(workflow: Workflow): void {
  if (
    workflow.id === '' ||
    workflow.tenantId === '' ||
    workflow.organizationId === '' ||
    workflow.tenantId !== workflow.organizationId ||
    workflow.nodes.length === 0
  )
    throw new ValidationError('Workflow organization and nodes are required');
  const ids = new Set(workflow.nodes.map((node) => node.id));
  if (
    workflow.nodes.some((node) => node.id === '') ||
    ids.size !== workflow.nodes.length ||
    workflow.edges.some((edge) => !ids.has(edge.from) || !ids.has(edge.to))
  )
    throw new ValidationError('Workflow graph is invalid');
  if (
    workflow.nodes.some(
      (node) => node.kind === 'Human Approval' && asApprovers(node.config.approvers).length === 0,
    )
  )
    throw new ValidationError('Human Approval nodes require approvers');
  for (const edge of workflow.edges) validateCondition(edge.condition);
  for (const node of workflow.nodes) timeoutMs(node);
  for (const node of workflow.nodes) retryPolicy(node);
  for (const node of workflow.nodes) outputLimitBytes(node);

  const outgoing = new Map<string, string[]>();
  for (const node of workflow.nodes) outgoing.set(node.id, []);
  for (const edge of workflow.edges) outgoing.get(edge.from)?.push(edge.to);

  const visiting = new Set<string>();
  const visited = new Set<string>();
  const visit = (nodeId: string): void => {
    if (visiting.has(nodeId)) throw new ValidationError('Workflow graph contains a cycle');
    if (visited.has(nodeId)) return;
    visiting.add(nodeId);
    for (const next of outgoing.get(nodeId) ?? []) visit(next);
    visiting.delete(nodeId);
    visited.add(nodeId);
  };
  for (const node of workflow.nodes) visit(node.id);
}

class WorkflowTimeoutError extends Error {
  constructor() {
    super('Workflow step timed out');
    this.name = 'WorkflowTimeoutError';
  }
}

class WorkflowOutputLimitError extends Error {
  constructor() {
    super('Workflow step output exceeds its configured limit');
    this.name = 'WorkflowOutputLimitError';
  }
}

class WorkflowOutputSerializationError extends Error {
  constructor() {
    super('Workflow step output cannot be serialized');
    this.name = 'WorkflowOutputSerializationError';
  }
}

function timeoutMs(node: WorkflowNode): number | undefined {
  const value = node.config.timeoutMs;
  if (value === undefined) return undefined;
  if (typeof value !== 'number' || !Number.isInteger(value) || value <= 0 || value > 86_400_000)
    throw new ValidationError('Workflow node timeoutMs must be an integer between 1 and 86400000');
  return value;
}

function outputLimitBytes(node: WorkflowNode): number | undefined {
  const value = node.config.maxOutputBytes;
  if (value === undefined) return undefined;
  if (!Number.isInteger(value) || value < 1 || value > 10_000_000)
    throw new ValidationError(
      'Workflow node maxOutputBytes must be an integer between 1 and 10000000',
    );
  return value;
}

function assertOutputWithinLimit(node: WorkflowNode, output: unknown): void {
  const limit = outputLimitBytes(node);
  if (limit === undefined) return;
  let serialized: string | undefined;
  try {
    serialized = JSON.stringify(output);
  } catch {
    throw new WorkflowOutputSerializationError();
  }
  const bytes = serialized === undefined ? 0 : new TextEncoder().encode(serialized).byteLength;
  if (bytes > limit) throw new WorkflowOutputLimitError();
}

function nextNode(edges: readonly WorkflowEdge[], from: string, output: unknown): string | undefined {
  return edges.find(
    (edge) => edge.from === from && (edge.condition === undefined || matchesCondition(edge.condition, output)),
  )?.to;
}

function validateCondition(condition: string | undefined): void {
  if (condition === undefined) return;
  const value = condition.trim();
  if (value === 'true' || value === 'false' || value === 'output.exists') return;
  if (/^output\s*(===|!==|==|!=)\s*.+$/.test(value)) {
    const literal = value.replace(/^output\s*(===|!==|==|!=)\s*/, '');
    try {
      JSON.parse(literal);
      return;
    } catch {
      // Fall through to the typed validation error below.
    }
  }
  throw new ValidationError('Workflow edge condition is not deterministic or valid');
}

function matchesCondition(condition: string, output: unknown): boolean {
  const value = condition.trim();
  if (value === 'true') return true;
  if (value === 'false') return false;
  if (value === 'output.exists') return output !== undefined && output !== null;
  const match = /^output\s*(===|!==|==|!=)\s*(.+)$/.exec(value);
  if (match === null) throw new ValidationError('Workflow edge condition is not deterministic or valid');
  const operator = match[1];
  const literal = match[2];
  if (operator === undefined || literal === undefined)
    throw new ValidationError('Workflow edge condition is not deterministic or valid');
  const expected = JSON.parse(literal);
  const equal = JSON.stringify(output) === JSON.stringify(expected);
  return operator === '!=' || operator === '!==' ? !equal : equal;
}

interface WorkflowRetryPolicy {
  readonly maxAttempts: number;
  readonly backoffMs: number;
}

function retryPolicy(node: WorkflowNode): WorkflowRetryPolicy {
  const value = node.config.retry;
  if (value === undefined) return { maxAttempts: 1, backoffMs: 0 };
  if (typeof value !== 'object' || value === null || Array.isArray(value))
    throw new ValidationError('Workflow node retry must be an object');
  const candidate = value as { readonly maxAttempts?: unknown; readonly backoffMs?: unknown };
  const maxAttempts = candidate.maxAttempts ?? 1;
  const backoffMs = candidate.backoffMs ?? 0;
  if (
    typeof maxAttempts !== 'number' ||
    !Number.isInteger(maxAttempts) ||
    maxAttempts < 1 ||
    maxAttempts > 10 ||
    typeof backoffMs !== 'number' ||
    !Number.isInteger(backoffMs) ||
    backoffMs < 0 ||
    backoffMs > 60_000
  )
    throw new ValidationError('Workflow node retry must use maxAttempts 1-10 and backoffMs 0-60000');
  return { maxAttempts, backoffMs };
}

function waitForRetryBackoff(delayMs: number, signal?: AbortSignal): Promise<void> {
  if (signal?.aborted === true) return Promise.reject(new Error('Workflow execution cancelled'));
  return new Promise<void>((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => finish(resolve), delayMs);
    const abort = () => {
      finish(() => reject(new Error('Workflow execution cancelled')));
    };
    signal?.addEventListener('abort', abort, { once: true });
    function finish(callback: () => void): void {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      signal?.removeEventListener('abort', abort);
      callback();
    }
  });
}

function sameWorkflowGraph(left: Workflow, right: Workflow): boolean {
  return JSON.stringify({ nodes: left.nodes, edges: left.edges }) ===
    JSON.stringify({ nodes: right.nodes, edges: right.edges });
}

function asApprovers(value: unknown): readonly string[] {
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === 'string')
    : [];
}
